('50b3573c-c48a-43f0-aaea-ebbeaba21fa3', '21feff02-016d-46e2-bb9d-c27495133b1b', '41. óra: Összetett műveletek, zárójelfelbontás', 'Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "f5a1069e-f503-45be-a6b5-7aecf2a3e7bb", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "d2d2bc09-9f20-4a24-9388-e3aa016ca349", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "406817b9-29ed-4a57-b76b-f2dc1327d5c1", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "a888d86e-fc72-42ee-bf0c-4119bf645b6d", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "c1603639-6847-4551-bfe7-72c8e34efed1", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "a29f7bab-1d51-45ab-a6b9-774e2b2d515f", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "53a614af-a1d0-4119-adfc-6571657fe43f", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "10202437-ae6f-4922-b214-57b706d1e864", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "18494d5f-1e0f-4c5e-9ddb-dc98eb41f3ac", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "735149e2-e874-48e1-ba1b-85b6b96e5616", "text": "Igaz", "isCorrect": true}, {"id": "80a1e92c-430b-4373-a4c3-d81e9a664353", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e1bf44f5-7630-4b77-9579-8e088c242024", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "d9932978-1dad-4205-8417-98cbf8dcb7e1", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
('3277aa84-5663-42a7-bbf8-07c263c64bad', '21feff02-016d-46e2-bb9d-c27495133b1b', '42. óra: Összetett műveletek, zárójelfelbontás gyakorlása', 'Gyakorlás feladatlapok és összetett kifejezések segítségével.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "4fb5acf5-a67d-4b1d-8b5e-87ed6f43ce2c", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "59ecc073-9df0-4c0c-b7d0-6f518ca20387", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "b3cf3e76-a07a-432f-91c5-0a34a58ab7cb", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "f935ff5d-c6ca-429c-90fd-4fbfe02399ce", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "9815bd39-f25a-4232-830b-adf487f61adf", "text": "Igaz", "isCorrect": true}, {"id": "0cc90102-7544-401f-a95f-b8ada9b96ab8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1fcb96bb-1f76-4ba3-adb0-d49198f03b45", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "c5b13c12-3b8a-4753-bc9c-ea29efe21c44", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "f380493e-3d73-4154-a706-94b07cbbaeab", "text": "Igaz", "isCorrect": true}, {"id": "d967e4cc-f3d9-463c-8383-4235cf524640", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0483f0b0-15a8-484f-9de8-0b3cd2febe88", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('a316f0c9-18ee-479e-9dd5-d5e1f9ef78c8', '21feff02-016d-46e2-bb9d-c27495133b1b', '43. óra: Összefoglalás', 'A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "40cba97b-3e27-494a-828a-d51a5605076a", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "5a62dc6e-065e-4687-9d13-5557d1d62a2c", "text": "3/5", "isCorrect": true}, {"id": "6af7dd51-96fb-421c-8be3-a77fd8e39f71", "text": "12/20", "isCorrect": false}, {"id": "f9eed60d-52d5-4e9b-87f1-b3fc888899be", "text": "7/9", "isCorrect": false}, {"id": "5a325c87-5078-4ff2-b0ed-d580c745e4ed", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "42a51e5a-94f1-4fb5-8d9e-006aebd0e76f", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "a371458b-59d4-4180-9959-3739d63976ae", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "189e61d9-65c8-49a6-a79a-b4fd5db8cbd9", "text": "1/6", "isCorrect": false}, {"id": "7a2cb526-5db4-40c1-8d08-5f0388ddf30d", "text": "2/3", "isCorrect": false}, {"id": "155ab365-548e-42e7-aa82-5d83aa70fa40", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "47113ca8-e797-4f5d-ac3a-873629a98de2", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "a505dc5d-136c-4797-bdd2-02515097e45a", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "84a00b05-4b9f-4591-aca4-519b0ab2e069", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "27726fea-a18c-4979-80b5-422796ed7db7", "text": "Igaz", "isCorrect": true}, {"id": "54cb0f96-9e19-44a1-8c6b-1d142592142f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1b73b7ba-ff3f-4fa5-8775-ede5d71e70a1", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "e59388e