('a75eaf8a-e57e-4428-be17-4b2ba6875373', '21feff02-016d-46e2-bb9d-c27495133b1b', '44. óra: Feladatmegoldás', 'Gyakorló feladatok megbeszélése egyéni és csoportmunkában.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "f8f542b1-476b-47a6-984a-45820b13b885", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "c3586f8b-d10a-4b89-b6f7-7b59b8a4d099", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "071da6a7-8b74-4290-8dc0-5338bd450298", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "8ce6879b-2073-4047-94ec-20a6873c3fa2", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "5e45c48c-26c3-43e0-b0ea-233820733c96", "text": "1/5", "isCorrect": false}, {"id": "d0ff04e1-fe0d-4ef0-acd5-f65778113fb2", "text": "1/2", "isCorrect": false}, {"id": "0311fd9d-2b04-4695-994c-914bbbbf44e4", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "220e244d-3477-4202-8ba4-90c0c49ad327", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "fe5e0e99-4acd-43ef-a9b3-5aafeac44916", "text": "Igaz", "isCorrect": true}, {"id": "b81b144f-877a-472e-bf1d-e00f2e42b6d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b666eeea-f30f-4223-9f8a-a1a57d0ac391", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "9e8e2e50-22c4-4a0b-b219-fb088b0145d9", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "d8e7f7d9-f49d-4f34-af55-88ebf8c092ea", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "cf745a03-1aca-4ce1-92b2-c8a36744c259", "text": "Igaz", "isCorrect": true}, {"id": "b59b7b7f-efb0-4e9d-8def-0c04c6be4bbe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('3c6d60b2-2b2f-4939-9c4d-06d5a8966841', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "82fcf5de-21c5-45d1-883d-dbde324cae22", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "84181204-a8ca-4e4c-a57b-6d80ad08d103", "text": "1/3", "isCorrect": true}, {"id": "d38d6fc4-2f43-4dfd-98bc-e9fc022c75e8", "text": "1/4", "isCorrect": false}, {"id": "2187f5d8-794c-46c8-85b8-324aa3d628c8", "text": "2/3", "isCorrect": false}, {"id": "e9038373-18a3-4c53-86e9-6704b1e19363", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "ea923b1d-9eca-4b31-98b7-a1c85fbe888e", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "aed82aaf-abb2-4464-987c-bfabce3f642f", "text": "1/4", "isCorrect": true}, {"id": "bde3143b-5cfa-4078-9222-a42678b95385", "text": "1/5", "isCorrect": false}, {"id": "06b56b56-343d-407b-8069-9695033da235", "text": "2/5", "isCorrect": false}, {"id": "847acfa1-1de5-48a8-9871-dcfd07d991ab", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "cc6939d5-feb3-4a31-85dd-1148ae9407bc", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "a2fe42bc-6891-418d-9349-c4bfbf6582f2", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e1453beb-eba7-4872-a9d6-b31cafdef8fd", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "0e4977ab-2a0a-4c51-933d-6014cd5a43d3", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "1d5e9371-9efa-4d1e-8a87-84d59c8458c5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "493fd4e3-ef04-4cef-baad-641716cecd7c", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "54005c3b-106d-45c5-8486-39a808857f13", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "2a698d66-3eeb-4102-a313-96cab37b4a2b", "text": "Igaz", "isCorrect": true}, {"id": "5de6518e-aa4e-4774-bee7-a94c2cda3239", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('8bb8abc1-d1b7-471c-8059-aade56cb0a4e', '21feff02-016d-46e2-bb9d-c27495133b1b', '46. óra: Témazáró dolgozat', 'Témazáró számonkérés a Törtek fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "d29f833c-9948-4288-839a-a5577730c2ae", "text": "1. Mennyi 2/3 + 1/6? (4/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "940f5d8d-efb3-425b-b01a-85add078a410", "text": "5/6", "isCorrect": true}, {"id": "cb6c4bcd-3c74-46aa-a50b-2a4e7442a9be", "text": "3/9", "isCorrect": false}, {"id": "297b5352-763e-4977-bffe-3815aa522dfe", "text": "3/6", "isCorrect": false}, {"id": "8704e8d5-eb80-4e7c-a485-db10c652245b", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "c1ddc889-537f-4e9b-aef5-5dd5db3da156", "text": "2. Mennyi 3/5 * 5/6?", "type": "multiple-choice", "options": [{"id": "00171614-adac-4898-bd97-c2c38975ad42", "text": "15/30 (azaz 1/2)", "isCorrect": true}, {"id": "483d458b-27d8-4649-b56d-4daaa2469227", "text": "8/11", "isCorrect": false}, {"id": "2aaf0c57-0bdd-40ec-9265-24118b7ae98f", "text": "15/11", "isCorrect": false}, {"id": "ffb16663-0296-4dff-832d-054e62e6614b", "text": "3/6", "isCorrect": false}], "timeLimit": 15}, {"id": "5aa65ee3-10e4-4afc-bcde-7f180f9663ec", "text": "3. Mennyi 3/4 : 1/2? (3/4 * 2/1)", "type": "multiple-choice", "options": [{"id": "792e8550-3691-4520-ab7b-f98306238639", "text": "6/4 (azaz 3/2 vagy 1,5)", "isCorrect": true}, {"id": "e6986201-d74f-4cb7-bea6-5ac9cb84a8bf", "text": "3/8", "isCorrect": false}, {"id": "7947433b-24e6-4b9e-bcb0-6bf11802ecf2", "text": "1/4", "isCorrect": false}, {"id": "80019d16-403b-46f1-833e-9c83776699e5", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "348d30e9-ad98-4f61-a27d-0eec56677b82", "text": "4. Mi a 4/9 reciproka?", "type": "multiple-choice", "options": [{"id": "bc2adf7f-b23f-4e29-8ccf-8ac8b47c06d9", "text": "9/4", "isCorrect": true}, {"id": "5fe38e65-e46a-4a8a-b933-adab9887e1ce", "text": "-4/9", "isCorrect": false}, {"id": "e96db0ad-0b7e-4216-b49d-5be4929d4101", "text": "1/4", "isCorrect": false}, {"id": "1bfcaf2b-f083-45af-b7c2-4509670759d4", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "72915779-79f0-4b8c-b6fa-0183d20b91a7", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "4bf28fb6-7218-4381-93b8-d98c939bef14", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "ca039567-b41c-442c-aee1-a03e3d3ba600", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "953af03e-37fb-4c8f-b5ff-f2416ea04841", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "f5088d3a-1d15-4224-807e-64a27bc74823", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "bb74f5a3-f7a1-40be-8c15-2e264b3c4a4f", "text": "Igaz", "isCorrect": true}, {"id": "5a526f90-6978-4091-8bdc-abb0fce84ea8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3fc133a1-5861-445f-920d-92ce26bc04b7", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()),
('bd43be00-6ee3-488f-a490-e5042729791b', '21feff02-016d-46e2-bb9d-c27495133b1b', '47. óra: Témazáró dolgozat értékelése', 'A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "7acc1dba-4ba8-4727-8734-619ff0d015e5", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "53c490b9-d586-436c-aeee-d8543c536e74", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "9948e02b-d59a-414d-bba1-64771de3c76d", "text": "A számlálók leírása", "isCorrect": false}, {"id": "6cc7955e-3c82-4a83-91e1-1bb80daf08b2", "text": "A zárójel használata", "isCorrect": false}, {"id": "2db51fcd-0df9-455d-a6ef-a5fe6f078445", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "8ab79c3f-b31c-455f-995d-a19dc37c5e7d", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "8533b8ca-46c2-4877-b877-60ae10878076", "text": "Igaz", "isCorrect": true}, {"id": "1d4d90c4-3517-4427-b724-1b87f785e61a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9a7940d4-de70-44e5-b6d0-50aa58bb8fcf", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "7ce72040-3da0-4f47-9b3d-984a4961c687", "text": "2/5", "isCorrect": true}, {"id": "455a5350-6876-485c-a5e9-cddba2ebaa4b", "text": "4/10", "isCorrect": false}, {"id": "24f167e1-57a5-44fb-b248-8542a00de573", "text": "1/5", "isCorrect": false}, {"id": "3dd25ee9-b544-4f62-862d-6641a4ad1a4a", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "4bebd532-b3da-4e28-9f08-499669322c78", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "49e2133e-6229-4f94-b75b-0d420c9766e7", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "3e8c18eb-b14e-4bbc-9c